[ ] Filename: thumbnail-${(state.idea || 'video').replace(/\s+/g,'-').slice(0,20).toLowerCase()}.jpg
 
── LAYOUT ${arch.id} SPECIFIC ─────────────
${getArchNotes(arch, state.emphasis)}
 
══════════════════════════════════════════
Generated by Thumb Studio (offline tool)
══════════════════════════════════════════`;
 
  document.getElementById('checklist-text').textContent = txt;
}
 
function getCropSafety(crop) {
  const m = {
    tight:    '[ ] Head NOT cropped at top\n[ ] Forehead has small gap to frame edge\n[ ] Eyes are above vertical midpoint\n[ ] Ear tips visible (unless extreme zoom)',
    mid:      '[ ] Full head visible with gap at top\n[ ] Hands/arms not cropped awkwardly\n[ ] Waist is the bottom crop line\n[ ] No furniture/floor cutting into frame oddly',
    wide:     '[ ] Horizon level (use grid overlay)\n[ ] Subject inside rule-of-thirds intersection\n[ ] No distracting objects touching subject edge\n[ ] Sky / ceiling not overblown',
    product:  '[ ] Product fully inside frame with padding\n[ ] No packaging creases visible\n[ ] Logo/branding facing camera\n[ ] Single clear hero angle',
    'text-only':'[ ] Background ≥60% contrast with text\n[ ] No busy texture behind text\n[ ] Gradient direction supports hierarchy\n[ ] Clear visual entry point (eye moves to headline)',
  };
  return m[crop] || '';
}
 
function getArchNotes(arch, emphasis) {
  const m = {
    A: `[ ] Hard diagonal split visible — slash from top-${emphasis==='left'?'right':'left'} to bottom\n[ ] Accent color stripe on ${emphasis==='left'?'right':'left'} half\n[ ] Text stacked bottom-${emphasis==='left'?'left':'right'}, bold Impact-style font`,
    B: `[ ] Subject occupies ${emphasis==='right'?'right':'left'} 40% of frame\n[ ] Color gradient bleeding in from subject side\n[ ] Headline spans center, visible against both panels`,
    C: `[ ] Text is the dominant element — large, centered\n[ ] Subject framed small or as BG element\n[ ] Strong border/box contains headline text`,
  };
  return m[arch.id] || '';
}
 
// ─── COPY ─────────────────────────────────────────────────────────────────────
function copyChecklist() {
  const text = document.getElementById('checklist-text').textContent;
  navigator.clipboard.writeText(text).then(() => {
    const btn = document.getElementById('copy-btn');
    btn.textContent = '✓ Copied!';
    setTimeout(() => btn.innerHTML = '&#9113; Copy checklist', 1800);
  }).catch(() => {
    // fallback
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    const btn = document.getElementById('copy-btn');
    btn.textContent = '✓ Copied!';
    setTimeout(() => btn.innerHTML = '&#9113; Copy checklist', 1800);
  });
}
 
// ─── RESET ────────────────────────────────────────────────────────────────────
function resetAll() {
  ['idea','channel','headline','subtext','subject'].forEach(id => document.getElementById(id).value = '');
  for (let i = 0; i < 3; i++) { cardData[i].headline = ''; cardData[i].subtext = ''; cardData[i].notes = ''; }
  document.getElementById('results-section').style.display = 'none';
  document.getElementById('checklist-section').style.display = 'none';
}
 
// ─── HELPERS ─────────────────────────────────────────────────────────────────
function escH(s) { return (s||'').replace(/"/g, '&quot;').replace(/</g, '&lt;'); }
 
// Polyfill roundRect for older browsers
if (!CanvasRenderingContext2D.prototype.roundRect) {
  CanvasRenderingContext2D.prototype.roundRect = function(x,y,w,h,r){
    this.beginPath();
    this.moveTo(x+r, y);
    this.lineTo(x+w-r, y);
    this.quadraticCurveTo(x+w, y, x+w, y+r);
    this.lineTo(x+w, y+h-r);
    this.quadraticCurveTo(x+w, y+h, x+w-r, y+h);
    this.lineTo(x+r, y+h);
    this.quadraticCurveTo(x, y+h, x, y+h-r);
    this.lineTo(x, y+r);
    this.quadraticCurveTo(x, y, x+r, y);
    this.closePath();
  };
}
 
// Redraw on resize
let resizeTimer;
window.addEventListener('resize', () => {
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(() => {
    if (document.getElementById('results-section').style.display !== 'none') {
      archetypes.forEach((arch, idx) => {
        const canvas = document.getElementById(`canvas-${idx}`);
        if (!canvas) return;
        const parent = canvas.parentElement;
        canvas.width  = parent.offsetWidth;
        canvas.height = parent.offsetHeight;
        drawCard(canvas, arch, cardData[idx]);
      });
      renderTinyStrip();
    }
  }, 150);
});
