<title>Thumb Studio — YouTube Thumbnail Planner</title>
<style>
  /* ── TOKENS ─────────────────────────────────────────────────────────── */
  :root {
    --ink:     #0d0d0f;
    --panel:   #1c1c22;
    --raise:   #242430;
    --border:  #2e2e3a;
    --muted:   #55556a;
    --dim:     #8888a2;
    --body:    #c4c4d6;
    --bright:  #ededf5;
    --accent:  #ff3f3f;
    --accent2: #ff8c42;
    --teal:    #3fffd8;
