    --bad:     #ff4f4f;
    --warn:    #f5c842;
    --r-sm: 4px; --r-md: 8px; --r-lg: 14px;
    --font-ui: 'Inter', system-ui, sans-serif;
    --font-mono: 'JetBrains Mono', 'Fira Mono', monospace;
    /* single source of truth for horizontal breathing room */
    --gutter: 12px;
  }
 
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
 
  /* Hard stop: nothing escapes the viewport */
  html, body {
    max-width: 100%;
    overflow-x: hidden;
  }
 
  body {
    background: var(--ink);
    color: var(--body);
    font-family: var(--font-ui);
    font-size: 14px;
    line-height: 1.5;
    min-height: 100vh;
  }
 
  /* ── APP SHELL ───────────────────────────────────────────────────────── */
  .app {
    width: 100%;
    max-width: 1120px;
    margin: 0 auto;
    padding: 20px var(--gutter) 80px;
  }
 
  /* ── HEADER ──────────────────────────────────────────────────────────── */
  .header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 24px;
    border-bottom: 1px solid var(--border);
    padding-bottom: 14px;
  }
  .header h1 { font-size: 17px; font-weight: 700; color: var(--bright); letter-spacing: -.3px; }
  .header h1 span { color: var(--accent); }
  .header p { font-size: 12px; color: var(--muted); }
 
  /* ── SECTION ─────────────────────────────────────────────────────────── */
  .section {
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: var(--r-lg);
    padding: 16px var(--gutter);
    margin-bottom: 14px;
    /* prevent children from escaping */
    overflow: hidden;
    min-width: 0;
  }
  .section-title {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .08em;
