<title>Thumb Studio — YouTube Thumbnail Planner</title>
<style>
  /* ── TOKENS ── */
  :root {
    --ink:     #0d0d0f;
    --panel:   #1c1c22;
    --raise:   #242430;
    --border:  #2e2e3a;
    --muted:   #55556a;
    --dim:     #8888a2;
    --body:    #c4c4d6;
    --bright:  #ededf5;
    --accent:  #ff3f3f;
    --accent2: #ff8c42;
    --teal:    #3fffd8;
    --good:    #3fde8a;
    --bad:     #ff4f4f;
    --warn:    #f5c842;
    --r-sm: 4px; --r-md: 8px; --r-lg: 14px;
    --font-ui: 'Inter', system-ui, sans-serif;
    --font-mono: 'JetBrains Mono', 'Fira Mono', monospace;
    /* single source of truth for horizontal breathing room */
    --gutter: 12px;
  }
 
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
 
  /* Hard stop: nothing escapes the viewport */
  html, body {
    max-width: 100%;
    overflow-x: hidden;
  }
 
  body {
    background: var(--ink);
    color: var(--body);
    font-family: var(--font-ui);
    font-size: 14px;
    line-height: 1.5;
    min-height: 100vh;
  }
 
  /* ── APP SHELL ── */
  .app {
    width: 100%;
    max-width: 1120px;
    margin: 0 auto;
    padding: 20px var(--gutter) 80px;
  }
 
  /* ── HEADER ── */
  .header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 24px;
    border-bottom: 1px solid var(--border);
    padding-bottom: 14px;
  }
  .header h1 { font-size: 17px; font-weight: 700; color: var(--bright); letter-spacing: -.3px; }
  .header h1 span { color: var(--accent); }
  .header p { font-size: 12px; color: var(--muted); }
 
  /* ── SECTION ── */
  .section {
    background: var(--panel);
    border: 1px solid var(--border);
    border-radius: var(--r-lg);
    padding: 16px var(--gutter);
    margin-bottom: 14px;
    /* prevent children from escaping */
    overflow: hidden;
    min-width: 0;
  }
  .section-title {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .08em;
    color: var(--muted);
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;          /* badge wraps on tiny screens */
  }
  .section-title .badge {
    background: var(--raise);
    color: var(--dim);
    border-radius: 20px;
    padding: 1px 7px;
    font-size: 9px;
    white-space: nowrap;
  }
 
  /* ── GRIDS — all collapse to 1-col below 520px ───────────────────────── */
  .grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
  .grid-3 { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 10px; }
 
  @media (max-width: 519px) {
    .grid-2, .grid-3 { grid-template-columns: 1fr; }
  }
 
  /* ── FORM CONTROLS ── */
  label {
    display: block;
    font-size: 10px;
    font-weight: 600;
    color: var(--dim);
    margin-bottom: 5px;
    text-transform: uppercase;
    letter-spacing: .05em;
  }
 
  input[type="text"], textarea, select {
    width: 100%;
    min-width: 0;              /* allow shrink inside grid cells */
    background: var(--raise);
    border: 1px solid var(--border);
    border-radius: var(--r-md);
    color: var(--bright);
    font-family: var(--font-ui);
    font-size: 16px;           /* ≥16px prevents iOS zoom */
    padding: 8px 10px;
    outline: none;
    transition: border-color .15s, box-shadow .15s;
  }
  input[type="text"]:focus, textarea:focus, select:focus {
    border-color: var(--accent);
    box-shadow: 0 0 0 3px rgba(255,63,63,.12);
  }
  textarea { resize: vertical; min-height: 52px; }
 
  /* ── PILL TOGGLES ── */
  .pill-group { display: flex; flex-wrap: wrap; gap: 6px; }
  .pill {
    cursor: pointer;
    background: var(--raise);
    border: 1px solid var(--border);
    border-radius: 100px;
    color: var(--dim);
