    font-weight: 600;
    padding: 4px 11px;
    transition: all .15s;
    user-select: none;
    white-space: nowrap;
  }
  .pill:hover { border-color: var(--accent); color: var(--body); }
  .pill.active { background: var(--accent); border-color: var(--accent); color: #fff; }
 
  /* ── BUTTONS ── */
  .btn-generate {
    flex: 1 1 auto;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    background: var(--accent);
    border: none;
    border-radius: var(--r-md);
    color: #fff;
    cursor: pointer;
    font-family: var(--font-ui);
    font-size: 14px;
    font-weight: 700;
