  .card-meta { padding: 10px 10px 12px; }
  .card-label {
    font-size: 10px;
    font-weight: 700;
    color: var(--accent2);
    text-transform: uppercase;
    letter-spacing: .06em;
    margin-bottom: 7px;
  }
  .card-field { margin-bottom: 7px; }
  .card-field label { margin-bottom: 3px; }
 
  .card-score-bar {
