  /* ── TINY STRIP ── */
  /* No negative margins — those fight .section's overflow:hidden.
     Canvases are sized in JS to fit the available width.            */
  .tiny-scroll-wrap {
    width: 100%;
    overflow: hidden;        /* clips any stray pixel; JS keeps content in range */
  }
  .tiny-strip {
    display: flex;
